            continue
        if indoc:
            cur.append(s)
            if s.endswith('-/'): indoc=False; doc=' '.join(cur)
            continue
        m=re.match(r'(theorem|def|abbrev|structure|inductive|instance)\b',s)
        if m:
            if doc is None: print(f,n,'NO DOC',s[:60])
            elif '§' not in doc: print(f,n,'NO §',s[:60])
            doc=None
        elif s and not s.startswith('--'):
            if not s.startswith('|') and not s.startswith('/-!'):
                pass
            doc=None if not s.startswith('/-') else doc
EOF

